const DOKRA_INFO={id:"dokra-art",title:"Dokra Art — The Lost-Wax Metal Craft",originRegion:"Bastar (Chhattisgarh), Dhenkanal (Odisha), Bankura (West Bengal)",eraOrigin:"Ancestral — traced to the Indus Valley (c. 2500 BCE)",heritageStatus:"Ancient tribal metal-casting heritage of India",technique:"Cire Perdue (Lost-Wax) Casting",quickStats:[{label:"Technique",value:"Lost-Wax (Cire Perdue) Casting",icon:"🪔"},{label:"Heritage",value:"Indus Valley Roots (c. 2500 BCE)",icon:"🏺"},{label:"Artisans",value:"Dokra Damar & Kamar Tribes",icon:"🧑‍🎨"},{label:"Materials",value:"Brass, Bronze, Beeswax & Clay",icon:"⚙️"},{label:"Key Centres",value:"Bastar, Dhenkanal, Bankura",icon:"🗺️"},{label:"Craft Name",value:"From the 'Dokra Damar' Smelters",icon:"📛"}]},HISTORY_CHAPTERS=[{title:"The Indus Valley Legacy",period:"c. 2500 BCE",description:"The bronze 'Dancing Girl' of Mohenjo-daro — cast by the lost-wax method some 4,500 years ago — is among the world's oldest metal sculptures. Dokra is regarded as its living descendant, carrying an unbroken chain of tribal metal casting through the millennia."},{title:"The Dokra Damar Smelters",period:"Ancient – Modern",description:"The craft takes its name from the Dokra Damar tribes, nomadic metal smiths of central and eastern India, who wandered the tribal belt casting ritual objects — gods, beasts and ornaments — at village doorsteps."},{title:"Regional Schools of Dokra",period:"19th – 20th Century",description:"Distinct clusters flowered in Bastar (Chhattisgarh), Dhenkanal and Mayurbhanj (Odisha), and Bankura and Midnapore (West Bengal), each developing its own gods, beasts and decorative motifs."},{title:"Ritual & Folk Iconography",period:"Continuous",description:"Mother goddesses, horses with riders, elephants, owls, musicians and lamp-holders serve tribal rituals, harvest festivals and household devotion — each figure an object of worship as much as an ornament."},{title:"Revival & Recognition",period:"20th Century – Present",description:"Handicraft boards, museums and export markets revived the craft after its mid-century decline. Today Dokra is celebrated worldwide as one of India's proudest tribal metal heritages."}],LOST_WAX_PROCESS=[{step:1,title:"Wax Model",description:"The artisan shapes the figure from fine beeswax with bare hands and simple tools, modelling every detail before any metal is touched."},{step:2,title:"Clay Core & Gates",description:"A clay core is formed, and the wax figure is fitted with sprue channels — 'gates' that will later carry the molten metal and release air."},{step:3,title:"The Mould",description:"Successive coats of clay mixed with paddy husk and dung encase the model, baking into a robust fire-proof mould."},{step:4,title:"Dewaxing",description:"The mould is heated over the furnace; the wax melts and runs out through the gates, leaving an exact hollow cavity — the 'lost wax'."},{step:5,title:"Pouring the Bronze",description:"Scrap brass or bronze is melted in a crucible and poured into the cavity once occupied by the wax."},{step:6,title:"Breaking & Finishing",description:"The cooled mould is broken away and the cast is cleaned, filed and polished — each piece made in one piece, with no seams, and no two ever alike."}],ARTISAN_COMMUNITIES=[{name:"The Dokra Damar Tribes",description:"The nomadic metal smiths of Jharkhand, Odisha, Chhattisgarh and West Bengal who gave the craft its name and carried its lost-wax lore across generations of travel."},{name:"The Kamar of Bastar",description:"The Kamar community of Chhattisgarh's Bastar district, celebrated for mother-goddess figures and tribal dancers cast in brass and bronze with deep folk symbolism."},{name:"The Dhenkanal & Bankura Schools",description:"Odisha's Dhenkanal cluster and West Bengal's Bankura Dhokra villages keep distinct regional iconographies alive — from horses and elephants to gods astride owls."}],GALLERY_IMAGES=[{url:"https://commons.wikimedia.org/wiki/Special:FilePath/Dancing_girl_of_Mohenjo-daro.jpg",caption:"The 'Dancing Girl' of Mohenjo-daro (2300–1750 BCE, National Museum, New Delhi) — the Indus Valley bronze cast by the same lost-wax method Dokra still uses.",category:"Heritage"},{url:"https://commons.wikimedia.org/wiki/Special:FilePath/Dokra_from_tribes_of_Bastar_DSCN1172_01.jpg",caption:"Dokra figures from the tribes of Bastar, Chhattisgarh — mother goddesses and tribal icons in brass and bronze.",category:"Bastar"},{url:"https://commons.wikimedia.org/wiki/Special:FilePath/God_astride_an_owl,_Dhokra_(Dokra)_craftsmen,_Bankura,_West_Bengal,_19th_century,_lost-wax_cast_brass,_HAA.JPG",caption:"God astride an owl — 19th-century lost-wax cast brass by Dhokra craftsmen of Bankura, West Bengal.",category:"Bankura"},{url:"https://commons.wikimedia.org/wiki/Special:FilePath/Dokra_Art.jpg",caption:"A Durga idol cast in Dokra craft — the festival goddess re-imagined in the tribal lost-wax idiom.",category:"Iconography"},{url:"https://commons.wikimedia.org/wiki/Special:FilePath/Dokra_art.png",caption:"Dokra metal casting in progress — the hollow, seamless forms that define the technique.",category:"Process"},{url:"https://commons.wikimedia.org/wiki/Special:FilePath/Tribal_Anklets_called_Andu_made_of_Bell_Metal_using_Dhokra_Craft_Technique,_Orissa.jpg",caption:"'Andu' tribal anklets of bell metal cast by the Dhokra technique, Odisha — Dokra extends beyond idols to ornament.",category:"Ornaments"}],REFERENCES=[{text:"Britannica — Lost-wax process (cire perdue) and Indian metalwork.",link:"https://www.britannica.com/art/lost-wax-process"},{text:"Sahapedia — Dhokra metal craft of India.",link:"https://www.sahapedia.org/dhokra-metal-craft"},{text:"Office of the Development Commissioner (Handicrafts) — Dhokra / Dokra craft.",link:"https://handicrafts.nic.in"},{text:"National Museum, New Delhi — The Dancing Girl of Mohenjo-daro.",link:"https://nationalmuseumindia.gov.in"}];"undefined"!=typeof module&&module.exports&&(module.exports={DOKRA_INFO:DOKRA_INFO,HISTORY_CHAPTERS:HISTORY_CHAPTERS,LOST_WAX_PROCESS:LOST_WAX_PROCESS,ARTISAN_COMMUNITIES:ARTISAN_COMMUNITIES,GALLERY_IMAGES:GALLERY_IMAGES,REFERENCES:REFERENCES});